function badge(s){return '<span class="badge '+s.replace(/ /g,'')+'">'+s+'</span>'}
function card(d){var info=d.info||('Status: '+d.status+' | Deadline: '+d.deadline+' | Check faculty CS page for university English vs scholarship English before applying.');return '<div class="card" data-r="'+d.region+'" data-s="'+d.status+'" data-e="'+d.eng+'" data-f="'+d.fund+'"><h3>'+d.c+' — '+d.s+'</h3><div class="row">'+badge(d.status)+'<span class="pill">'+d.fund+'</span><span class="pill">'+d.eng+'</span></div><div class="meta"><b>Deadline:</b> '+d.deadline+'</div><div class="meta"><b>CS:</b> '+d.cs+'</div><div class="meta"><b>BD:</b> '+d.bd+' | <b>Fit:</b> '+d.fit+'</div><details><summary>Full detail - no re-research needed</summary><div class="meta">'+info+'</div></details><a href="'+d.link+'" target="_blank" rel="noopener">Official source</a></div>'}
function render(){
var q=document.getElementById('q').value.toLowerCase(),r=document.getElementById('fRegion').value,s=document.getElementById('fStatus').value,e=document.getElementById('fEnglish').value,f=document.getElementById('fFund').value;
var out='',open='';
var nOpen=0,nFull=0;
for(var i=0;i<DATA.length;i++){var d=DATA[i];if(d.status.indexOf('OPEN NOW')>-1)nOpen++;if(d.fund==='Full')nFull++;}
for(var j=0;j<DATA.length;j++){var x=DATA[j];var hay=(x.c+' '+x.s+' '+x.cs+' '+x.fit).toLowerCase();
if(q&&hay.indexOf(q)<0)continue;if(r&&x.region!==r)continue;if(s&&x.status!==s)continue;if(e&&x.eng.indexOf(e)<0)continue;if(f&&x.fund!==f)continue;
out+=card(x);if(x.status==='OPEN NOW')open+=card(x);}
document.getElementById('grid').innerHTML=out;document.getElementById('openNow').innerHTML=open||'<div class="meta">No open-now match with current filters.</div>';
document.getElementById('empty').hidden=out!=='';
document.getElementById('stats').innerHTML='<span class="stat">'+DATA.length+' routes</span><span class="stat">'+nOpen+' open now</span><span class="stat">'+nFull+' full-funded</span><span class="stat">195-country check</span>';
var cb='';for(var k=0;k<CLOSED.length;k++){cb+='<tr><td>'+CLOSED[k][0]+'</td><td>'+CLOSED[k][1]+'</td><td>'+CLOSED[k][2]+'</td></tr>';}
document.getElementById('closedBody').innerHTML=cb;
var co='';for(var m=0;m<COUNTRIES.length;m++){co+='<details open><summary>'+COUNTRIES[m][0]+'</summary><p class="meta">'+COUNTRIES[m][1]+'</p></details>';}
document.getElementById('countries').innerHTML=co;
}
document.getElementById('q').addEventListener('input',render);document.getElementById('fRegion').addEventListener('change',render);document.getElementById('fStatus').addEventListener('change',render);document.getElementById('fEnglish').addEventListener('change',render);document.getElementById('fFund').addEventListener('change',render);render();
